#include <iostream>
using namespace std;

int main() {
    int mark;
    cout << "Enter marks (0-100): ";
    cin >> mark;
    while (mark < 0 || mark > 100) {
        cout << "Invalid. Enter marks (0-100): ";
        cin >> mark;
    }
    cout << "Accepted: " << mark << endl;
    return 0;
}

#include <iostream>
using namespace std;

bool isValidMark(int m) {
    return m >= 0 && m <= 100;
}

int main() {
    int tests[6] = {-1, 0, 1, 99, 100, 101};
    for (int i = 0; i < 6; i++) {
        cout << tests[i] << " -> ";
        if (isValidMark(tests[i])) {
            cout << "valid" << endl;
        } else {
            cout << "invalid" << endl;
        }
    }
    return 0;
}

#include <iostream>
using namespace std;

int readChoice() {
    int choice;
    while (true) {
        cout << "Choice (1-4): ";
        if (cin >> choice && choice >= 1 && choice <= 4) {
            return choice;
        }
        cout << "Bad input, try again." << endl;
        cin.clear();
        cin.ignore(1000, '\n');
    }
}

int main() {
    int c = readChoice();
    cout << "You chose " << c << endl;
    return 0;
}

